js.text:

function grid$hrdmnv(f){
  this.constructor(f);
}
grid$hrdmnv.prototype = new DirEvent();
grid$hrdmnv.prototype.afterInit = function(){
  var p = this._dir;

  if(!p.options._isReload){
    p.options._isReload = true;

    $('<div class="left-panel-tree" id="tree_left"><div id="tree_dept" class="tree-top"></div><div id="tree_info" class="tree-bottom"></div></div>').insertBefore("#content");
    p.request('GetTreeInfo', 'GetDataSet', null, grid$hrdmnv$loadTree);

    var s = '<button class="btn-action btn-action-v1" id="btnTreeAction"><div class="icon-btn-bottom ic-hide-tree" id="ic_btn_action_tree"></div></button>'
    $("#content").append(s);

    $("#btnTreeAction").click(function () {
        var icBtn = $("#ic_btn_action_tree");
        if (!p.options._isShow){
          p.options._isShow = true;

          var curLeft = $("#content").css("margin-left");

          moveLeft("tree_left", "-=" + curLeft);
          moveLeft("content", "-=" + curLeft);

          setTimeout(function(){
            icBtn.removeClass("ic-hide-tree");
            icBtn.addClass("ic-show-tree");
          }, 300);
        }else{
          p.options._isShow = false;

          var curLeft = $("#tree_left").css("width");
          moveLeft("tree_left", "+=" + curLeft);
          moveLeft("content", "+=" + curLeft);

          setTimeout(function(){
            icBtn.removeClass("ic-show-tree");
            icBtn.addClass("ic-hide-tree");
          }, 300);
        }
    });
  }
}

function moveLeft(id, action){
  $("#" + id).animate({
      marginLeft: action
  }, 500);
}

function grid$hrdmnv$loadTree(p, d) {
  d = new DataSet(d);
  grid$hrdmnv$loadTreeDept(p, d.get(0));
  grid$hrdmnv$loadTreeInfo(p, d.get(1));
}

function grid$hrdmnv$loadTreeDept(p, d) {
  var leftPanel = $("#tree_left");
  var treeBottom = $("#tree_info");
  var dContent = $("#content");
  var fTree = $("#tree_dept").treeview({ tblData: d, expandAll: true, showCheck: true, minWidth: 95, inRight: false
      , onSelectedGoods: function(tr, v, v2){
        var m = p.options.memvars, vtext = (v == '')?$.msg.get('AllLabel'):v;
        m.val('ma_bp', 'C', v2, 'FIND')
        p._setOptions({memvars:m, subtitle: ['{rg_code}', vtext, '%s2', '']});
      }, onCheckedGoods: function(tr, v, flag){
        var m = p.options.memvars, v2 = tr.getCheckedGoods(), vtext = (v2 == '') ? $.msg.get('AllLabel') : v2;
        m.val('ma_bp', 'C', v2, 'FIND')
        p._setOptions({memvars:m, subtitle: ['{rg_code}', vtext, '%s2', '']});
      }, onResizeTree: function(tr, w){
        leftPanel.width(w);
        dContent.css("margin-left", w + "px");
        refreshSizeGridDir();
      }
    });
}
function grid$hrdmnv$loadTreeInfo(p, d){
  var i, id, d2, lastLevel = -1, s = '<div class="bottom-resize" id="bar_resize_grid"></div><div class="bottom-econtainer"><ul class="bottom-einfo clearfix">', r1 = d.findRow('[xlevel] == 1');
  for(i = 0; i < r1.length; i++){
    s += "<li class='" + d.val(r1[i], "id").replace(".", "").replace(".", "") + "'>" + d.val(r1[i], "xheader") + "</li>";
  }
  s += '</ul></div';
  $(s).insertAfter(p.element);

  var funMenuClick = function(controller) {
    var g = p.grid(), r = g._currRow;
    if (r != null) {
      var opt, m = new Memvars(), idnv = p.valGrid(r, 'id');
      m.val('id', 'I', idnv);
      if (controller.indexOf('!') != 0)
        opt = $.extend({}, { controller: controller, folder: "Grid", dirViewType: "Lookup", parent: p, memvars: m, lookupOk: false, _id: idnv, title: ['%s', p.valGrid(r, 'ho_ten_nv')]}, {});
      else {
        controller = controller.substr(1);
        m.val('action', 'C', 'EDIT').val('copy', 'I', 0)
        opt = $.extend({}, { controller: controller, folder: "Dir", dirViewType: "Dialog", parent: p, memvars: m, action: "EDIT", _id: idnv, title: ['%s', p.valGrid(r, 'ho_ten_nv')]}, {});
      }
      $.createDir(false, opt);
    }else
      $.showToast('$selectEmploy', p);
  }

  var btm = p.element.parent().find('.bottom-econtainer');
  for(i = 0; i < r1.length; i++){
    id = d.val(r1[i], "id");
    d2 = d.clone(['id', 'xheader', 'xcode'], "[id0] == '" + id + "'");
    if (d2.count()){
      id = id.replace(".", "").replace(".", "");
      btm.find('.' + id).menu({id: 'HRMENU_' + id, type: "hover", data: d2, parent: p, columsSource: ["id", "xheader"], click: function(po, xid, index){
        funMenuClick(this.data.val(index, "xcode"));
        po.hide();
      }}).append($("<div class='arrow-up'></div>"));
    }else {
      btm.find('.' + id.replace(".", "").replace(".", "")).click(function(){
        var index = d.findRow("[xid] == '" + this.classList[0] + "'")[0];
        funMenuClick(d.val(index, "xcode"));
      })
    }
  }

  var gridDir = $("#content").find(".dir:eq(0)");
  var dMenu = $(".bottom-econtainer")
  $("#bar_resize_grid").boxresize({ divBox1: gridDir, divBox2: dMenu, minValue1: 200, minValue2: 10, resizeWidth: false,});



  refreshSizeGridDir();
  $(window).resize(function() {
    refreshSizeGridDir();
  });
}

function refreshSizeGridDir(){
  var wHeight = $(window).height(), hBar = 70;
  if($(window).width() < 767)
    hBar = 60;
  var con = $("#content");
  con.css("height", (wHeight - hBar) + "px");
  con.find(".dir:eq(0)").css("height", "calc(100% - " + con.find('.bottom-econtainer').outerHeight() + "px)");
}

css.text:

.table-bottom{
	left: 0px!important;
	height: calc(100% - 77px);
	top: 0px;
	position: relative;
	margin-top: 27px;
	clear: both;
	border-bottom: 1px solid #ddd;
}
#content .dir{
	position: relative !important;
	height: 100%;
}

@media only screen and (max-width: 767px) {
  .table-bottom{
	margin-top: 42px;
	height: calc(100% - 92px);
  }
}


#content{
  margin-left: 300px;
}
.tree-form{
    width: 300px;
}
.table-bottom{
  height: calc(100% - 77px);
  top: 0px;
  position: relative;
  margin-top: 27px;
  clear: both;
  border-bottom: 1px solid #ddd;
}
.left-panel-tree{
  width: 300px;
  height: 100%;
  position: absolute;
  margin-left: 1px;
}
#DIR_hrdmnv_Grid{
  position: relative !important;
  height: 9999px;;
}

.ic-hide-tree{
  background-position: -108px 0px;
}
.ic-show-tree{
  background-position: 0px 0px;
}

.tree-top{
  height: calc(100% - 70px);
}
.tree-panel{
  border-right: 1px solid #ddd;
}
@media only screen and (max-width: 767px) {
  .table-bottom{
    margin-top: 42px;
    height: calc(100% - 92px);
  }
  .left-panel-tree{
    margin-top: -5px;
  }
}

.bottom-einfo > li {
    float: left;
    width: auto;
    text-align: center;
    border: 1px solid #ddd;
    padding-left: 10px;
    padding-right: 10px;
    margin-left: 10px;
    margin-top: 5px;
}
.bottom-einfo {
    padding-left: 0px;
}

    .bottom-einfo > li {
        line-height: 30px;
        list-style: none;
    }

        .bottom-einfo > li.active, .bottom-einfo > li:hover {
            color: #007acc;
            background-color: #F2F7FD;
            cursor: pointer;
        }

.bottom-econtainer{
  height: auto;
  width: auto;
  overflow: hidden;
  padding-right: 80px;
  bottom: 0px;
  position: absolute;
  background: #fff;
  margin-left: 1px;
}
#subcontent div:has(.dir)
{
  top: 0px;
  left: 0px;
  width: 100%;
  height: 100%;
}
